contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Seed the caller's account with a known positive balance and unlock time already in the past.
        c.Put{value: depositAmount}(0);

        (uint beforeUnlock, uint beforeBal) = c.Acc(msg.sender);
        uint cBefore = address(c).balance;

        // The only state-changing call under test.
        c.Collect(collectAmount);

        (uint afterUnlock, uint afterBal) = c.Acc(msg.sender);
        uint cAfter = address(c).balance;

        // General rule: after Put, a Collect that actually moved value must have brought the
        // caller's balance all the way down to exactly the requested amount (and the contract
        // must have paid out exactly that amount).  When nothing was collected, the recorded
        // balance and the contract's Ether are unchanged.
        bool noPayout = (beforeBal == afterBal);
        bool fullPayout = (afterBal == 0 && beforeBal == collectAmount);
        assert(noPayout ? (afterBal == beforeBal && cAfter == cBefore)
                        : (fullPayout && cAfter == cBefore - collectAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint collectAmount, uint unlockTime) public payable {
        require(address(this).balance >= depositAmount);

        // Seed the caller's account with a known positive balance and an explicit unlock time.
        c.Put{value: depositAmount}(unlockTime);

        (uint beforeUnlock, uint beforeBal) = c.Acc(msg.sender);
        uint cBefore = address(c).balance;

        // The only state-changing call under test.
        c.Collect(collectAmount);

        (, uint afterBal) = c.Acc(msg.sender);
        uint cAfter = address(c).balance;

        // General rule: If the caller's recorded balance decreased, then the call must have
        // satisfied the payout conditions (balance >= MinSum, block.timestamp > unlockTime,
        // balance >= collectAmount) and the Ether paid out must equal exactly the decrease in
        // the caller's recorded balance.
        bool decreased = (afterBal < beforeBal);
        assert(!decreased || (
            beforeBal >= c.MinSum() &&
            block.timestamp > beforeUnlock &&
            beforeBal >= collectAmount &&
            beforeBal - afterBal == collectAmount &&
            cBefore - cAfter == collectAmount
        ));
    }

    receive() external payable {}
}

